package com.samanramezani1377.woogit.data.local

import com.samanramezani1377.woogit.core.domain.entity.EntityId
import com.samanramezani1377.woogit.core.domain.entity.StoreId
import com.samanramezani1377.woogit.core.domain.error.CoreResult
import com.samanramezani1377.woogit.core.domain.error.DomainError
import com.samanramezani1377.woogit.core.domain.model.*
import com.samanramezani1377.woogit.core.domain.repository.*
import com.samanramezani1377.woogit.data.db.WooGitDatabase
import kotlinx.datetime.Instant
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json

private val json = Json { ignoreUnknownKeys = true; explicitNulls = false }
@Serializable private data class A(val first_name:String?=null,val last_name:String?=null,val company:String?=null,val address_1:String?=null,val address_2:String?=null,val city:String?=null,val state:String?=null,val postcode:String?=null,val country:String?=null,val phone:String?=null)
@Serializable private data class L(val id:Long=0,val product_id:Long=0,val variation_id:Long=0,val name:String="",val quantity:Double=0.0,val subtotal:String="0",val total:String="0")
@Serializable private data class S(val method_id:String?=null,val method_title:String?=null,val total:String?=null)
@Serializable private data class C(val code:String="",val discount:String="0")
@Serializable private data class O(val id:Long,val number:String="",val status:String="",val total:String?=null,val currency:String?=null,val customer_id:Long=0,val billing:A?=null,val shipping:A?=null,val payment_method:String?=null,val payment_method_title:String?=null,val transaction_id:String?=null,val date_modified_gmt:String?=null,val line_items:List<L> = emptyList(),val shipping_lines:List<S> = emptyList(),val coupon_lines:List<C> = emptyList())
@Serializable private data class I(val id:Long?=null,val src:String="",val name:String?=null,val alt:String?=null)
@Serializable private data class N(val id:Long=0,val name:String="")
@Serializable private data class X(val id:Long?=null,val name:String="",val visible:Boolean=true,val variation:Boolean=false,val options:List<String> = emptyList())
@Serializable private data class P(val id:Long,val name:String="",val sku:String?=null,val description:String?=null,val short_description:String?=null,val status:String="draft",val type:String="simple",val regular_price:String?=null,val sale_price:String?=null,val on_sale:Boolean=false,val stock_quantity:Double?=null,val stock_status:String="instock",val manage_stock:Boolean=false,val images:List<I> = emptyList(),val categories:List<N> = emptyList(),val attributes:List<X> = emptyList(),val date_modified_gmt:String?=null)
private fun A.d()=Address(first_name,last_name,company,address_1,address_2,city,state,postcode,country,phone)
private fun O.d()=Order(EntityId(id.toString()),when(status){"pending"->OrderStatus.PENDING;"processing"->OrderStatus.PROCESSING;"on-hold"->OrderStatus.ON_HOLD;"completed"->OrderStatus.COMPLETED;"cancelled"->OrderStatus.CANCELLED;"refunded"->OrderStatus.REFUNDED;"failed"->OrderStatus.FAILED;else->OrderStatus.OTHER},customer_id.takeIf{it!=0L}?.let{Customer(EntityId(it.toString()),listOfNotNull(billing?.first_name,billing?.last_name).joinToString(" "),billing?.phone)},billing?.d(),shipping?.d(),Payment(payment_method,payment_method_title,transaction_id,payment_method!=null),shipping_lines.map{ShippingLine(it.method_id,it.method_title,it.total)},coupon_lines.map{Discount(it.code,it.discount)},emptyList(),line_items.map{OrderItem(EntityId(it.id.toString()),it.product_id.takeIf{v->v!=0L}?.let{v->EntityId(v.toString())},it.variation_id.takeIf{v->v!=0L}?.let{v->EntityId(v.toString())},it.name,it.quantity,it.subtotal,it.total)},date_modified_gmt?.let(Instant::parse),number.ifBlank{id.toString()},total,currency)
private fun P.d()=Product(EntityId(id.toString()),name,sku,description,short_description,when(status){"publish"->ProductStatus.PUBLISHED;"pending"->ProductStatus.PENDING;"private"->ProductStatus.PRIVATE;else->ProductStatus.DRAFT},when(type){"grouped"->ProductType.GROUPED;"external"->ProductType.EXTERNAL;"variable"->ProductType.VARIABLE;else->ProductType.SIMPLE},Pricing(regular_price,sale_price,on_sale),Stock(stock_quantity,when(stock_status){"outofstock"->StockStatus.OUT_OF_STOCK;"onbackorder"->StockStatus.ON_BACKORDER;else->StockStatus.IN_STOCK},manage_stock),images.map{ProductImage(it.id?.let { id -> EntityId(id.toString()) },it.src,it.name,it.alt)},categories.map{IdName(EntityId(it.id.toString()),it.name)},attributes.map{Attribute(it.id?.let { id -> EntityId(id.toString()) },it.name,it.visible,it.variation,it.options)},date_modified_gmt)
class SqlOrderDataSource(private val db:WooGitDatabase):LocalOrderDataSource<Order>{
 override fun get(storeId:StoreId,id:EntityId):CoreResult<Order> = db.orderQueries.selectById(id.value,storeId.value).executeAsOneOrNull()?.let{CoreResult.Success(json.decodeFromString<O>(it.payload_json).d())}?:CoreResult.Failure(DomainError.NotFound("order",id.value))
 override fun list(storeId:StoreId):CoreResult<List<Order>> = CoreResult.Success(db.orderQueries.selectByStore(storeId.value).executeAsList().map{json.decodeFromString<O>(it.payload_json).d()})
 override fun upsert(storeId:StoreId,value:Order):CoreResult<Unit>{val now=System.currentTimeMillis();db.orderQueries.upsert(value.id.value,storeId.value,value.status.name,0,value.currency ?: "",value.modifiedAt?.toString() ?: "",value.modifiedAt?.toString() ?: "",json.encodeToString(O(value.id.value.toLongOrNull()?:0L,value.number,value.status.name.lowercase(),value.total,value.currency,value.customer?.id?.value?.toLongOrNull()?:0L,value.billing?.let{A(it.firstName,it.lastName,it.company,it.address1,it.address2,it.city,it.state,it.postcode,it.country,it.phone)},value.shipping?.let{A(it.firstName,it.lastName,it.company,it.address1,it.address2,it.city,it.state,it.postcode,it.country,it.phone)},value.payment?.methodId,value.payment?.methodTitle,value.payment?.transactionId,value.modifiedAt?.toString(),value.items.map{L(it.id.value.toLongOrNull()?:0L,it.productId?.value?.toLongOrNull()?:0L,it.variationId?.value?.toLongOrNull()?:0L,it.name,it.quantity,it.subtotal,it.total)},value.shippingLines.map{S(it.methodId,it.methodTitle,it.total)},value.discounts.map{C(it.code,it.total)})),now,now);return CoreResult.Success(Unit)}
 override fun delete(storeId:StoreId,id:EntityId):CoreResult<Unit>{db.orderQueries.deleteById(id.value,storeId.value);return CoreResult.Success(Unit)}
}
class SqlProductDataSource(private val db:WooGitDatabase):LocalProductDataSource<Product>{
 override fun get(storeId:StoreId,id:EntityId):CoreResult<Product> = db.productQueries.selectById(id.value,storeId.value).executeAsOneOrNull()?.let{CoreResult.Success(json.decodeFromString<P>(it.payload_json).d())}?:CoreResult.Failure(DomainError.NotFound("product",id.value))
 override fun list(storeId:StoreId):CoreResult<List<Product>> = CoreResult.Success(db.productQueries.selectByStore(storeId.value).executeAsList().map{json.decodeFromString<P>(it.payload_json).d()})
 override fun upsert(storeId:StoreId,value:Product):CoreResult<Unit>{val now=System.currentTimeMillis();db.productQueries.upsert(value.id.value,storeId.value,value.name,value.status.name,value.pricing.regular?.toLongOrNull(),null,value.stock?.quantity?.toLong(),value.modifiedAt?:"",value.modifiedAt?:"",json.encodeToString(P(value.id.value.toLongOrNull()?:0L,value.name,value.sku,value.description,value.shortDescription,value.status.name.lowercase(),value.type.name.lowercase(),value.pricing.regular,value.pricing.sale,value.pricing.onSale,value.stock?.quantity,value.stock?.status?.name?.lowercase() ?: "instock",value.stock?.manageStock ?: false,value.images.map{I(it.id?.value?.toLongOrNull(),it.src,it.name,it.alt)},value.categories.map{N(it.id.value.toLongOrNull()?:0L,it.name)},value.attributes.map{X(it.id?.value?.toLongOrNull(),it.name,it.visible,it.variation,it.options)},value.modifiedAt)),now,now);return CoreResult.Success(Unit)}
 override fun delete(storeId:StoreId,id:EntityId):CoreResult<Unit>{db.productQueries.deleteById(id.value,storeId.value);return CoreResult.Success(Unit)}
}
class SqlStoreDataSource(private val db:WooGitDatabase):LocalStoreDataSource<StoreConnection>{
 override fun get(storeId:StoreId):CoreResult<StoreConnection> = db.storeQueries.selectById(storeId.value).executeAsOneOrNull()?.let{CoreResult.Success(StoreConnection(StoreId(it.id),it.base_url,ConnectionState.valueOf(it.connection_state),it.credential_reference?.let(::CredentialReference)))}?:CoreResult.Failure(DomainError.NotFound("store",storeId.value))
 fun findConnectedStoreId(): String? = db.storeQueries.selectAll().executeAsList().firstOrNull { it.connection_state == ConnectionState.CONNECTED.name && !it.credential_reference.isNullOrBlank() }?.id
 override fun upsert(value:StoreConnection):CoreResult<Unit>{val now=System.currentTimeMillis();db.storeQueries.insert(value.storeId.value,value.baseUrl,value.credentialReference?.value,value.state.name,now,now);return CoreResult.Success(Unit)}
 override fun delete(storeId:StoreId):CoreResult<Unit>{db.storeQueries.deleteById(storeId.value);return CoreResult.Success(Unit)}
}
